<template>
  <div class="container">
    
    
    <main class="content-wrapper">
      <!-- Single image upload section -->
      <section class="card upload-section">
        <div class="card-header" style="display: flex; justify-content: center; align-items: center; height: 80px;">
  <h2>Image Upload</h2>
</div>
        <div class="card-body">
          <form @submit.prevent="handleSubmit" class="upload-form">
            <label for="imageInput" class="file-label">
              <span class="file-icon">
                <i class="fas fa-upload"></i>
              </span>
              <span class="file-text" v-if="!imageFile">Click or drag image here to upload</span>
              <span class="file-text" v-if="imageFile">{{ imageFile.name }}</span>
              <input 
                type="file" 
                id="imageInput" 
                name="image" 
                accept="image/*" 
                required
                @change="handleImageChange"
                class="file-input"
              >
            </label>
            <button type="submit" class="btn btn-primary upload-btn" :disabled="!imageFile || isLoading">
              <span v-if="!isLoading">Upload and Detect</span>
              <span v-if="isLoading">
                <i class="fas fa-spinner fa-spin"></i> Processing...
              </span>
            </button>
          </form>
          
          <!-- Preview image with fixed height and scrolling -->
          <div v-if="imagePreviewUrl" class="image-preview-container">
            <h3 class="preview-title">Preview</h3>
            <div class="image-scroll-container">
              <img 
                :src="imagePreviewUrl" 
                alt="Preview image" 
                class="image-preview"
                @load="onImageLoad('preview')"
                :style="previewImageStyle"
              >
            </div>
          </div>
        </div>
      </section>

      <!-- Results section -->
      <section class="card results-section">
       <div class="card-header" style="display: flex; justify-content: center; align-items: center; height: 80px;">
  <h2>Single Image Detection Results</h2>
</div>
        <div class="card-body">
          <div id="detectionResults" class="results-content">
            <!-- Loading state -->
            <div v-if="isLoading" class="status-indicator loading">
              <i class="fas fa-circle-notch fa-spin"></i>
              <p>Detecting, please wait...</p>
            </div>
            
            <!-- Error message -->
            <div v-if="errorMessage" class="status-indicator error">
              <i class="fas fa-exclamation-circle"></i>
              <p>{{ errorMessage }}</p>
              <p v-if="debugInfo" class="debug-info">{{ debugInfo }}</p>
            </div>
            
            <!-- Single image detection results list -->
            <div v-if="detections.length > 0 && !isLoading && !errorMessage" class="detections-list">
              <p class="results-summary">Detected <span class="count">{{ detections.length }}</span> cucumbers:</p>
              <ul>
                <li v-for="(obj, index) in detections" :key="index" class="detection-item">
                  <div class="detection-class">{{ obj.class }}</div>
                  <div class="detection-meta">
                    <span class="confidence">Confidence: {{ obj.confidence.toFixed(2) }}</span>
                    <span class="position">Position: {{ formatBox(obj.box) }}</span>
                  </div>
                </li>
              </ul>
            </div>
            
            <!-- No results state -->
            <div v-if="detections.length === 0 && !isLoading && !errorMessage && hasResults" class="status-indicator empty">
              <i class="fas fa-search"></i>
              <p>No cucumbers detected</p>
            </div>
          </div>
          
          <!-- Annotated image with fixed height and scrolling -->
          <div v-if="annotatedImageUrl && !isLoading && !errorMessage" class="result-image-container">
            <h3 class="result-image-title">Annotated Result</h3>
            <div class="image-scroll-container">
              <img 
                :src="annotatedImageUrl" 
                class="result-image" 
                alt="Detection result image"
                @load="onImageLoad('result')"
                :style="resultImageStyle"
              >
            </div>
          </div>
        </div>
      </section>
    </main>
    
    <footer class="page-footer">
      <p>Cucumber Detection System &copy; 2025</p>
    </footer>
  </div>
</template>


<script setup>
import { ref } from 'vue';

// 状态管理
const imageFile = ref(null);
const imagePreviewUrl = ref('');
const detections = ref([]);
const annotatedImageUrl = ref('');
const isLoading = ref(false);
const errorMessage = ref('');
const debugInfo = ref(''); // 调试信息
const hasResults = ref(false);
const networkDebug = ref(''); // 网络调试信息

// 图片样式状态 - 用于等比例缩放
const previewImageStyle = ref({});
const resultImageStyle = ref({});
const MAX_IMAGE_HEIGHT = 400; // 最大图片高度
const MAX_IMAGE_WIDTH = 800;  // 最大图片宽度

// 处理图片加载，计算等比例缩放尺寸
const onImageLoad = (type) => {
  const img = new Image();
  const styleRef = type === 'preview' ? previewImageStyle : resultImageStyle;
  const url = type === 'preview' ? imagePreviewUrl.value : annotatedImageUrl.value;
  
  img.src = url;
  img.onload = () => {
    let { width, height } = img;
    
    // 计算等比例缩小的尺寸
    if (height > MAX_IMAGE_HEIGHT) {
      const ratio = MAX_IMAGE_HEIGHT / height;
      width *= ratio;
      height = MAX_IMAGE_HEIGHT;
    }
    
    if (width > MAX_IMAGE_WIDTH) {
      const ratio = MAX_IMAGE_WIDTH / width;
      height *= ratio;
      width = MAX_IMAGE_WIDTH;
    }
    
    // 设置图片样式
    styleRef.value = {
      width: `${width}px`,
      height: `${height}px`,
      maxWidth: '100%'
    };
  };
};

// 处理单张图片选择
const handleImageChange = (e) => {
  const file = e.target.files[0];
  if (file) {
    imageFile.value = file;
    // 生成预览图
    const reader = new FileReader();
    reader.onload = (event) => {
      imagePreviewUrl.value = event.target.result;
    };
    reader.readAsDataURL(file);
    
    // 重置网络调试信息
    networkDebug.value = '';
    debugInfo.value = '';
  }
};

// 格式化边界框显示
const formatBox = (box) => {
  return box.map(coord => coord.toFixed(2)).join(', ');
};

// 重置结果状态
const resetResults = () => {
  detections.value = [];
  annotatedImageUrl.value = '';
  errorMessage.value = '';
  hasResults.value = false;
  resultImageStyle.value = {}; // 重置结果图片样式
};

// 带超时的fetch请求 - 延长超时时间至30秒
const fetchWithTimeout = (url, options, timeout = 30000) => {
  return Promise.race([
    fetch(url, options),
    new Promise((_, reject) => 
      setTimeout(() => reject(new Error(`Request timed out after ${timeout}ms`)), timeout)
    )
  ]);
};

// 处理单张图片上传检测 - 适配后端成功响应
const handleSubmit = async () => {
  if (!imageFile.value) return;
  
  // 重置状态
  isLoading.value = true;
  resetResults();
  networkDebug.value = `Starting upload at ${new Date().toISOString()}\n`;
  debugInfo.value = '';
  
  try {
    const formData = new FormData();
    formData.append('image', imageFile.value);
    
    // 补充文件元信息（帮助后端更清晰处理）
    formData.append('filename', imageFile.value.name);
    formData.append('filesize', imageFile.value.size);
    
    networkDebug.value += `File: ${imageFile.value.name} (${(imageFile.value.size / 1024).toFixed(2)}KB)\n`;
    networkDebug.value += `Target URL: https://123.56.203.202:8082/detect\n`;
    console.log(networkDebug.value);
    
    const response = await fetchWithTimeout('https://123.56.203.202:8082/detect', {
      method: 'POST',
      body: formData,
      // 仅在确定后端需要跨域Cookie时保留，否则移除
      // credentials: 'include'
    }, 30000);

    networkDebug.value += `Response status: ${response.status} (${response.statusText})\n`;
    networkDebug.value += `Response headers: ${JSON.stringify([...response.headers.entries()].slice(0, 5))}\n`;
    console.log(networkDebug.value);
    
    // 关键：后端返回200但前端仍报错时，优先检查响应格式
    const responseText = await response.text();
    networkDebug.value += `Response size: ${responseText.length} characters\n`;
    console.log('Raw response content:', responseText);
    
    // 新增：如果响应为空，单独处理
    if (!responseText.trim()) {
      throw new Error('Server returned empty response');
    }
    
    debugInfo.value = `Server response: ${responseText.substring(0, 500)}...`;
    
    if (!response.ok) {
      throw new Error(`Server returned error (${response.status}): ${responseText.substring(0, 200)}`);
    }

    // 解析JSON（后端成功处理但前端解析失败是常见问题点）
    let data;
    try {
      data = JSON.parse(responseText);
      networkDebug.value += 'JSON parsed successfully\n';
      console.log('Parsed data:', data);
      
      // 验证后端返回结构是否符合预期
      if (!Array.isArray(data.detections)) {
        throw new Error('Server returned invalid detections format (expected array)');
      }
    } catch (parseError) {
      networkDebug.value += `JSON parse error: ${parseError.message}\n`;
      console.error('JSON parsing failed:', parseError);
      // 新增：提供更具体的解析错误提示
      throw new Error(`Failed to parse response: ${parseError.message}\nCheck if server returns valid JSON`);
    }
    
    if (data.error) {
      throw new Error(data.error);
    }
    
    // 更新状态（确保与后端返回字段匹配）
    hasResults.value = true;
    detections.value = data.detections || [];
    
    // 显示标注后的图片（检查base64格式是否正确）
    if (data.annotated_image) {
      // 验证base64字符串有效性
      if (typeof data.annotated_image === 'string' && data.annotated_image.length > 100) {
        annotatedImageUrl.value = `data:image/jpg;base64,${data.annotated_image}`;
      } else {
        console.warn('Invalid base64 image from server');
        debugInfo.value += '\nWarning: Received invalid annotated image data';
      }
    }

  } catch (error) {
    console.error('Detection error:', error);
    errorMessage.value = `Detection failed: ${error.message}`;
    
    // 优化错误分类，特别针对后端成功但前端解析失败的情况
    if (error.message.includes('Failed to parse response')) {
      debugInfo.value = `Data format mismatch: ${error.message}\n${networkDebug.value}`;
    } else if (error.message.includes('timed out')) {
      debugInfo.value = `Timeout: Server didn't respond within 30 seconds.\n${networkDebug.value}`;
    } else if (error.message.includes('Failed to fetch')) {
      debugInfo.value = `Network error: Could not connect to server.\n${networkDebug.value}`;
    } else if (error.message.includes('ECONNRESET')) {
      debugInfo.value = `Connection reset: Possible SSL certificate issue.\n${networkDebug.value}`;
    } else {
      debugInfo.value = `${error.message}\n${networkDebug.value}`;
    }
  } finally {
    isLoading.value = false;
    networkDebug.value += `Request completed at ${new Date().toISOString()}\n`;
    console.log(networkDebug.value);
  }
};

</script>
    

<style scoped>
